const remoteDeviceCounts = `-- name: RemoteDeviceCounts :many
SELECT a.user_id, count(DISTINCT ip)::integer AS devices
FROM node_alive a
JOIN nodes n ON n.id = a.node_id, unnest(a.ips) AS ip
WHERE a.updated_at >= $1::timestamptz
  AND n.host <> $2::text
  AND a.user_id = ANY($3::bigint[])
GROUP BY a.user_id
`

type RemoteDeviceCountsParams struct {
	Since   time.Time
	Host    string
	UserIds []int64
}

type RemoteDeviceCountsRow struct {
	UserID  int64
	Devices int32
}

// 限制了设备数的用户在这台机器以外的节点上的在线设备数。
func (q *Queries) RemoteDeviceCounts(ctx context.Context, arg RemoteDeviceCountsParams) ([]RemoteDeviceCountsRow, error) {
	rows, err := q.db.Query(ctx, remoteDeviceCounts, arg.Since, arg.Host, arg.UserIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []RemoteDeviceCountsRow{}
	for rows.Next() {
		var i RemoteDeviceCountsRow
		if err := rows.Scan(&i.UserID, &i.Devices); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

